import json
import re
from datetime import datetime, timezone

_TYPES = ("login", "view", "purchase", "refund")
_FINANCIAL = ("purchase", "refund")

_TS_RE = re.compile(
    r"^(\d{4})-(\d{2})-(\d{2})[Tt](\d{2}):(\d{2}):(\d{2})"
    r"(?:\.(\d{1,9}))?"
    r"([Zz]|[+-]\d{2}:\d{2})$"
)

_AMOUNT_RE = re.compile(r"^\d+(?:\.\d{1,2})?$")


def _line_error(n, message):
    return ValueError("line %d: %s" % (n, message))


def _check_surrogates(value, n, field):
    for ch in value:
        if 0xD800 <= ord(ch) <= 0xDFFF:
            raise _line_error(n, "unpaired surrogate in %s" % field)


def _normalize_id(value, n, field):
    if not isinstance(value, str):
        raise _line_error(n, "%s must be a string" % field)
    _check_surrogates(value, n, field)
    trimmed = value.strip()
    if not trimmed:
        raise _line_error(n, "%s is blank" % field)
    return trimmed


def _normalize_timestamp(value, n):
    if not isinstance(value, str):
        raise _line_error(n, "timestamp must be a string")
    _check_surrogates(value, n, "timestamp")
    match = _TS_RE.match(value)
    if not match:
        raise _line_error(n, "invalid timestamp")
    year, month, day, hour, minute, second = (
        int(match.group(1)),
        int(match.group(2)),
        int(match.group(3)),
        int(match.group(4)),
        int(match.group(5)),
        int(match.group(6)),
    )
    frac = match.group(7) or ""
    tz = match.group(8)
    try:
        dt = datetime(year, month, day, hour, minute, second, tzinfo=timezone.utc)
    except ValueError:
        raise _line_error(n, "invalid timestamp")
    if tz not in ("Z", "z"):
        sign = 1 if tz[0] == "+" else -1
        offset = timezone(sign * __import__("timedelta").timedelta(
            hours=int(tz[1:3]), minutes=int(tz[4:6])))
        dt = dt.replace(tzinfo=offset)
    dt = dt.astimezone(timezone.utc)
    micro = int(frac.ljust(6, "0")[:6])
    dt = dt.replace(microsecond=micro)
    return dt.strftime("%Y-%m-%dT%H:%M:%S.") + "%06dZ" % micro


def _normalize_amount(value, n):
    if not isinstance(value, str):
        raise _line_error(n, "amount must be a string")
    _check_surrogates(value, n, "amount")
    if not _AMOUNT_RE.match(value):
        raise _line_error(n, "invalid amount")
    if "." in value:
        whole, frac = value.split(".")
        frac = (frac + "00")[:2]
    else:
        whole, frac = value, "00"
    return "%s.%s" % (whole, frac)


def _parse_event(line, n):
    try:
        obj = json.loads(line)
    except ValueError:
        raise _line_error(n, "invalid JSON")
    if not isinstance(obj, dict):
        raise _line_error(n, "event must be an object")

    expected = {"event_id", "user_id", "timestamp", "type"}
    if obj.get("type") in _FINANCIAL:
        expected.add("amount")
    if set(obj.keys()) != expected:
        raise _line_error(n, "unexpected fields")

    event_id = _normalize_id(obj["event_id"], n, "event_id")
    user_id = _normalize_id(obj["user_id"], n, "user_id")
    timestamp = _normalize_timestamp(obj["timestamp"], n)
    etype = obj["type"]
    if etype not in _TYPES:
        raise _line_error(n, "invalid type")

    normalized = {
        "event_id": event_id,
        "user_id": user_id,
        "timestamp": timestamp,
        "type": etype,
    }
    if etype in _FINANCIAL:
        normalized["amount"] = _normalize_amount(obj["amount"], n)
    return normalized


def aggregate_events(text):
    events = []
    duplicate_count = 0
    seen = {}

    for n, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        normalized = _parse_event(line, n)
        key = normalized["event_id"]
        if key in seen:
            if seen[key] == normalized:
                duplicate_count += 1
            else:
                raise _line_error(n, "conflicting duplicate event_id")
        else:
            seen[key] = normalized
            events.append(normalized)

    events.sort(key=lambda e: (e["timestamp"], e["event_id"]))

    users = {}
    for event in events:
        user = users.setdefault(event["user_id"], {
            "user_id": event["user_id"],
            "first_seen": event["timestamp"],
            "last_seen": event["timestamp"],
            "counts": {t: 0 for t in _TYPES},
            "revenue_cents": 0,
        })
        ts = event["timestamp"]
        if ts < user["first_seen"]:
            user["first_seen"] = ts
        if ts > user["last_seen"]:
            user["last_seen"] = ts
        user["counts"][event["type"]] += 1
        if event["type"] in _FINANCIAL:
            whole, frac = event["amount"].split(".")
            cents = int(whole) * 100 + int(frac)
            if event["type"] == "purchase":
                user["revenue_cents"] += cents
            else:
                user["revenue_cents"] -= cents

    user_list = []
    for user_id in sorted(users):
        user = users[user_id]
        cents = user["revenue_cents"]
        sign = "-" if cents < 0 else ""
        cents = abs(cents)
        net = "%s%d.%02d" % (sign, cents // 100, cents % 100)
        user_list.append({
            "user_id": user["user_id"],
            "first_seen": user["first_seen"],
            "last_seen": user["last_seen"],
            "counts": user["counts"],
            "net_revenue": net,
        })

    return {
        "total_unique": len(events),
        "duplicate_count": duplicate_count,
        "ordered_events": events,
        "users": user_list,
    }
"}

